import{_ as p,o as t,c as a,a4 as _}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"当“鱼米之乡”遇上“智造之城”——江苏苏州以科技赋能农业现代化2026-06-04","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"当“鱼米之乡”遇上“智造之城”——江苏苏州以科技赋能农业现代化2026-06-04","date":"2026-06-04T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202606/t20260617_6485056.htm","summary":"农民日报全媒体记者　陈兵　李文博\\n苏湖熟,天下足——之于今天的江苏省苏州市,分量依旧沉甸甸。\\n作为经济高度发达、寸土寸金的城市,苏州始终将农业摆在突出位置,农村改革发展一直是全国的研究样板。在土地资源紧约束下,苏州把农业发展、农民致富的突破口放在了科技上,当“鱼米之乡”遇上“智造之城”,田间地头的农业生产,彻底变了模样。\\n...\\n","contentHash":"2856a95264c4c0b549e01bac94e3518f","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-06-04-当-鱼米之乡-遇上-智造之城-江苏苏州以科技赋能农业现代化.md","filePath":"policies/2026-06-04-当-鱼米之乡-遇上-智造之城-江苏苏州以科技赋能农业现代化.md"}'),s={name:"policies/2026-06-04-当-鱼米之乡-遇上-智造之城-江苏苏州以科技赋能农业现代化.md"};function r(o,e,n,c,l,i){return t(),a("div",null,[...e[0]||(e[0]=[_('<h1 id="当-鱼米之乡-遇上-智造之城-——江苏苏州以科技赋能农业现代化2026-06-04" tabindex="-1">当“鱼米之乡”遇上“智造之城”——江苏苏州以科技赋能农业现代化2026-06-04 <a class="header-anchor" href="#当-鱼米之乡-遇上-智造之城-——江苏苏州以科技赋能农业现代化2026-06-04" aria-label="Permalink to &quot;当“鱼米之乡”遇上“智造之城”——江苏苏州以科技赋能农业现代化2026-06-04&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202606/t20260617_6485056.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-06-04 摘要: 农民日报全媒体记者　陈兵　李文博 苏湖熟,天下足——之于今天的江苏省苏州市,分量依旧沉甸甸。 作为经济高度发达、寸土寸金的城市,苏州始终将农业摆在突出位置,农村改革发展一直是全国的研究样板。在土地资源紧约束下,苏州把农业发展、农民致富的突破口放在了科技上,当“鱼米之乡”遇上“智造之城”,田间地头的农业生产,彻底变了模样。 ...</p></blockquote><p>苏湖熟,天下足——之于今天的江苏省苏州市,分量依旧沉甸甸。</p><p>作为经济高度发达、寸土寸金的城市,苏州始终将农业摆在突出位置,农村改革发展一直是全国的研究样板。在土地资源紧约束下,苏州把农业发展、农民致富的突破口放在了科技上,当“鱼米之乡”遇上“智造之城”,田间地头的农业生产,彻底变了模样。</p><p>稻麦种植,AI技术全程跟着,作物长势、田间情况不用人工挨个儿跑,系统自动分析统计,效率比人工高了8倍,农情数据准确率还能稳定在90%以上,科技种地的好处,一眼就能看见。</p><p>这些年苏州抓农业农村工作,科技创新是实打实的核心抓手。2025年首届苏州科技强农大会召开,全市农业科技创新全面起势,到2026年更是系统成势,一步一个脚印走得格外扎实。2025年,苏州农业科技进步贡献率攀升至76.8%,稳稳站在全国第一方阵。</p><p>千年“鱼米之乡”,从来没有停下农业向前的脚步。科技硬核赋能,政策精准护航,再加上全链条的产业生态培育,苏州现代农业蹄疾步稳,给乡村全面振兴注入满满动能,更彰显出东部经济发达地区发展现代农业的责任与担当。</p><p>种子是农业的“芯片”,也是苏州科技强农最核心的发力点。</p><p>在基因技术前沿赛道,苏州本土企业实现“从0到1”的颠覆性突破。苏州拉索生物芯片科技有限公司,沉下心深耕6年,投入近3亿元研发资金,终于在2024年攻克固相芯片核心点制技术,打破了国外的技术垄断,成为全球第三家、国内首家也是唯一一家能自主研发、生产并商业化运营高密度固相芯片的企业,补上了国内这个领域的产业空白。</p><p>目前,拉索生物育种芯片已实现猪、鸡、牛、羊4大畜禽品种,玉米、小麦、大豆、水稻4大粮食作物,共8大类物种全覆盖,推动育种从“经验型”向“精准型”跨越式转型。凭着过硬的自主研发和国产替代实力,2025年还牵头主持国家农业科技重大项目,成为苏州生物育种与种业自主创新的标杆。</p><p>困扰行业多年的百合种球种性退化、抗性减弱难题,苏州也拿出了解决方案。张家港市常阴沙现代农业示范园区,将联手中国农业科学院蔬菜花卉研究所,建起华东地区百合重点育种基地,用脱毒复壮、品种选育技术,提升种球抗病能力,还将搭建起育种、生产、示范、推广的全产业链,规划繁育规模达3000万粒,给全国百合产业发展提供了苏州方案。</p><p>如今的苏州田野,智慧农业遍地开花。稻麦种植、水产养殖、蔬菜管护、茶果管理,到处都是无人化、智能化的生产场景。吴中区研发的“谷语大模型”,是江苏首个通过中央网信办备案的农业大模型,把气象、土壤、作物生长数据全整合起来,给农户种地、产业链管理出谋划策。</p><p>2025年,苏州设施农业总产值达到105.7亿元,创历史新高;高端农机装备有3230台(套),智能化清洁能源烘干机占比达到74%;通过专项政策与协同攻关,一批国产智能装备实现突破应用,无人化智慧生产模式初步形成……科技让农业生产变得更高效、更精准,也更可持续。</p><p>苏州农业科创成果亮眼,不禁让人琢磨,它为什么能遍地开花,是否可复制可借鉴?带着这些疑问,记者采访了一些农业科创企业梳理发现,他们提到一个共同点,那就是苏州的政策支持给力。</p><p>据了解,自2025年4月苏州召开首届科技强农大会,便同步出台了《苏州市科技强农行动计划(2025—2027年)》,部署8大行动、24项具体任务,明确34个核心指标,从顶层设计到落地细则,全方位为农业创新保驾护航。政府主动靠前服务,让企业不用操心琐事,专心搞研发、谋发展。</p><p>资金难题,苏州用财政金融双向发力破解。专门设立20亿元农业科创基金,推行“拨改投”改革,用长期“耐心资本”培育科技企业,重点扶持种业、智慧农业等有自主知识产权的项目,和企业共担风险,助力技术研发和成果转化。2025年,苏州推动46个农业科技企业增资扩产,总投资45亿元,已完成投资20.4亿元。真金白银的支持,让企业发展更有底气。</p><p>急企业所急,想企业所想,苏州持续以“揭榜挂帅”的方式,广发英雄帖,聚焦产业刚需、破解技术堵点,为加快培育农业新质生产力注入引发质变的“催化剂”。</p><p>创新要靠人才,苏州深谙这个道理。创新柔性引才方式,搭建科技小院、教授工作站等平台,建起5类农业人才库;实施乡村创客培育工程,累计培养1971名定向委培生,每年培训乡村创客超万人次,源源不断为农业科技输送本土专业人才,激活创新内生动力。</p><p>服务也跟得上。苏州专门成立科技强农大会秘书处,定期调度项目进展,推行一站式、保姆式服务,全程对接584家农业科技主体,从项目签约、投产到研发、推广,全程帮忙解决难题。贴心服务换来了企业认可,以商引商、增资扩产形成良性循环,农业创新产业集群越做越大。</p><p>2025年,苏州新增8个农业新品种、17件植物新品种权,种业产值首次突破50亿元,建成粮食生产智能农机应用场景24个。一项项科研成果走出实验室,走进田间地头,从苏州走向全国,实现了创新价值和产业效益的双丰收。</p><p>一花独放不是春,万紫千红春满园。苏州下辖10个县市区,没有搞同质化发展,而是立足各自资源禀赋,走出了特色鲜明的农业科技之路,形成“一板块一特色、一区域一优势”的全域格局,给不同类型的农业创新企业,提供了多元发展的舞台。</p><p>昆山市专攻食品科技,集聚40多家咖啡企业,全国60%的咖啡豆在这里集散,打造出集加工、研发、贸易于一体的咖啡全产业链;吴中区聚焦丘陵农业,研发推广农业机器人,破解丘陵地带机械化作业难题,让碧螺春茶、杨梅等特色农产品品质更优;苏州工业园区发力动物生物医药,汇聚领军企业,建起研发、生产、诊断、治疗的完整产业体系;吴江区、常熟市主打智能农机,激光除草、智能采摘等新设备落地应用,给高端农机企业提供了示范场景。</p><p>全域统筹、互补协同,是苏州农业创新的鲜明特点。从平原稻麦到丘陵茶果,从水产养殖到食品加工,从种业创新到智慧装备,各板块错位发力、优势互补。企业落户苏州,既能享受全市统一的政策红利,又能依托地方特色对接产业链资源,实现“1+1&gt;2”的发展效果。</p><p>立足当下,更谋长远。2026年,苏州以农业科技创新为核心引擎,聚焦技术攻关、产业融合、数智赋能、要素保障、治理优化五大方向,全力打造全国领先的农业科创高地。重点培育生物育种、合成生物学、农产品精深加工产业集群,力争打造1个百亿级、3个十亿级特色产业集群,让农业科技产业更具竞争力。</p><p>风禾尽起,未来可期。从种业“中国芯”到田间“新农具”,从精准政策扶持到全域生态共建,苏州的优势愈发凸显。这座城市正以科技为翼、政策为帆、生态为壤,携手全国更多农业创新企业,共建现代农业新高地,共绘乡村振兴新蓝图,为加快建设农业强国贡献苏州力量、彰显苏州担当!</p><p><a href="https://scs.moa.gov.cn/gzdt/202606/t20260617_6485056.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',26)])])}const m=p(s,[["render",r]]);export{f as __pageData,m as default};
